```sql
SELECT u.id AS user_id, u.name, u.region, o.id AS order_id, o.amount, oi.product_id, oi.quantity, oi.unit_price FROM users u JOIN orders o ON u.id = o.user_id JOIN order_items oi ON o.id = oi.order_id WHERE u.region = 'North America'   AND o.status = 'completed'   AND oi.quantity >= 3   AND oi.unit_price > 50.0 ORDER BY o.amount DESC LIMIT 50;
```

```sql
SELECT e.id AS event_id, e.user_id, u.name, e.event_type, e.created_at, e.payload FROM events e JOIN users u ON e.user_id = u.id WHERE e.payload LIKE '%"status": "failed"%'   AND e.payload LIKE '%"response_status": 500%'   AND u.name LIKE '%Smith%' ORDER BY e.created_at DESC LIMIT 50;
```

```sql
SELECT u.region, o.status,        COUNT(o.id) AS total_orders,        AVG(o.amount) AS avg_order_amount,        SUM(o.amount) AS total_revenue FROM orders o JOIN users u ON o.user_id = u.id WHERE o.amount >= 200.0   AND o.order_date >= '2024-01-01' GROUP BY u.region, o.status HAVING SUM(o.amount) > 25000.0 ORDER BY total_revenue DESC;
```

```sql
SELECT u.id, u.name, u.region, u.signup_date FROM users u WHERE EXISTS (     SELECT 1 FROM orders o     WHERE o.user_id = u.id       AND o.status = 'completed'       AND o.amount > 750.0       AND o.order_date >= '2025-01-01' ) ORDER BY u.id ASC LIMIT 100;
```

```sql
SELECT id, user_id, event_type, created_at, payload FROM events WHERE event_type = 'checkout_initiated' ORDER BY created_at DESC LIMIT 50 OFFSET 1000;
```

```sql
SELECT e.id, e.name, d.dept_name, e.salary FROM employees e JOIN departments d ON e.department_id = d.id WHERE (     SELECT COUNT(*)     FROM employees e2     WHERE e2.department_id = e.department_id       AND e2.salary > e.salary ) < 3 ORDER BY d.dept_name ASC, e.salary DESC;
```

```sql
SELECT oi.product_id,        COUNT(DISTINCT oi.order_id) AS total_distinct_orders,        SUM(oi.quantity) AS total_units_sold,        ROUND(SUM(oi.quantity * oi.unit_price), 2) AS total_sales_value,        ROUND(AVG(oi.unit_price), 2) AS avg_unit_price FROM order_items oi JOIN orders o ON oi.order_id = o.id WHERE (oi.quantity * oi.unit_price) >= 150.0   AND o.status NOT IN ('cancelled', 'refunded') GROUP BY oi.product_id HAVING SUM(oi.quantity * oi.unit_price) > 5000.0 ORDER BY total_sales_value DESC LIMIT 25;
```

